<?php
declare(strict_types=1);require __DIR__.'/app/admin.php';$user=require_nonagon_admin();$adminView=in_array($_GET['view']??'overview',['overview','accounts','investment'],true)?$_GET['view']:'overview';$pageTitle=['overview'=>'Admin overview','accounts'=>'Account access','investment'=>'Investment governance'][$adminView];require __DIR__.'/includes/admin-header.php';
if($adminView==='overview'):
 $metrics=rows("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM users WHERE is_active=1) active_users,(SELECT COUNT(*) FROM investment_opportunities) opportunities,(SELECT COUNT(*) FROM investment_investor_profiles WHERE kyc_status='PENDING') pending_kyc")[0];$statusRows=rows('SELECT status,COUNT(*) total FROM investment_opportunities GROUP BY status ORDER BY total DESC');$events=rows('SELECT e.*,u.full_name FROM nonagon_admin_events e JOIN users u ON u.id=e.actor_user_id ORDER BY e.id DESC LIMIT 12');?>
<header class="admin-heading"><div><h1>Platform overview</h1><p>Account, opportunity and investor-governance status.</p></div><a class="admin-button primary" href="admin?view=investment">Open review queue</a></header><section class="admin-metrics"><article><span>Total accounts</span><strong><?= number_format((int)$metrics['users']) ?></strong></article><article><span>Active accounts</span><strong><?= number_format((int)$metrics['active_users']) ?></strong></article><article><span>Investment opportunities</span><strong><?= number_format((int)$metrics['opportunities']) ?></strong></article><article><span>Pending investor KYC</span><strong><?= number_format((int)$metrics['pending_kyc']) ?></strong></article></section><div class="admin-grid"><section class="admin-panel"><h2>Opportunity pipeline</h2><?php foreach($statusRows as $row):?><p><span class="admin-badge <?= strtolower($row['status']) ?>"><?= e(str_replace('_',' ',$row['status'])) ?></span> <strong><?= (int)$row['total'] ?></strong></p><?php endforeach;?></section><section class="admin-panel"><h2>Recent administration</h2><?php foreach($events as $event):?><p><strong><?= e(str_replace('_',' ',$event['event_type'])) ?></strong><small><?= e($event['full_name']) ?> · <?= e($event['created_at']) ?></small></p><?php endforeach;?><?php if(!$events):?><p>No administrative actions recorded yet.</p><?php endif;?></section></div>
<?php elseif($adminView==='accounts'):$accounts=rows('SELECT u.*,o.name organization_name,(SELECT COUNT(*) FROM user_scopes s WHERE s.user_id=u.id) scope_count FROM users u JOIN owners o ON o.id=u.owner_id ORDER BY u.created_at DESC');?>
<header class="admin-heading"><div><h1>Account access</h1><p>Activate accounts, verify email ownership and manage application roles.</p></div></header><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Organization</th><th>Role</th><th>Email</th><th>State</th><th>Access controls</th></tr></thead><tbody><?php foreach($accounts as $account):?><tr><td><strong><?= e($account['full_name']) ?></strong><small><?= e($account['email']) ?></small></td><td><?= e($account['organization_name']) ?></td><td><span class="admin-badge"><?= e($account['role']) ?></span></td><td><span class="admin-badge <?= $account['is_email_verified']?'verified':'' ?>"><?= $account['is_email_verified']?'Verified':'Unverified' ?></span></td><td><span class="admin-badge <?= $account['is_active']?'active':'' ?>"><?= $account['is_active']?'Active':'Disabled' ?></span></td><td><div class="admin-actions"><?php if($account['id']!==$user['id']):?><form action="admin-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="account_state"><input type="hidden" name="id" value="<?= e($account['id']) ?>"><button name="is_active" value="<?= $account['is_active']?'0':'1' ?>"><?= $account['is_active']?'Disable':'Enable' ?></button></form><?php endif;?><?php if(!$account['is_email_verified']):?><form action="admin-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="verify_email"><input type="hidden" name="id" value="<?= e($account['id']) ?>"><button>Mark verified</button></form><?php endif;?><form action="admin-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="account_role"><input type="hidden" name="id" value="<?= e($account['id']) ?>"><select name="role"><?php foreach(['OWNER_ADMIN','ADMIN','OPS_MANAGER','SUPERVISOR','OPERATOR'] as $role):?><option <?= $account['role']===$role?'selected':'' ?>><?= $role ?></option><?php endforeach;?></select><button>Update role</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:$profiles=rows("SELECT p.*,u.full_name,u.email,o.name organization_name FROM investment_investor_profiles p JOIN users u ON u.id=p.user_id JOIN owners o ON o.id=p.organization_id ORDER BY FIELD(p.kyc_status,'PENDING','NOT_STARTED','REJECTED','VERIFIED'),p.updated_at DESC");$opportunities=rows("SELECT o.*,own.name organization_name,u.full_name creator_name,(SELECT COUNT(*) FROM investment_due_diligence_reviews r WHERE r.opportunity_id=o.id AND r.status='APPROVED') approved_reviews FROM investment_opportunities o JOIN owners own ON own.id=o.organization_id JOIN users u ON u.id=o.created_by ORDER BY o.updated_at DESC");?>
<header class="admin-heading"><div><h1>Investment governance</h1><p>Human review and approval of investors and investment opportunities.</p></div><a class="admin-button" href="investment-funding-admin">Funding control</a></header><section class="admin-panel"><h2>Investor verification</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Investor</th><th>Organization</th><th>Identity / tax</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($profiles as $profile):?><tr><td><?= e($profile['legal_name']) ?><small><?= e($profile['email']) ?></small></td><td><?= e($profile['organization_name']) ?></td><td><?= e($profile['identity_reference']?:'Not supplied') ?><small><?= e($profile['tax_reference']?:'No tax reference') ?></small></td><td><span class="admin-badge <?= strtolower($profile['kyc_status']) ?>"><?= e($profile['kyc_status']) ?></span></td><td><div class="admin-actions"><form action="admin-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="investor_kyc"><input type="hidden" name="id" value="<?= e($profile['user_id']) ?>"><button name="status" value="VERIFIED">Verify</button><button name="status" value="REJECTED">Reject</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="admin-panel"><h2>Opportunity review and approval</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Opportunity</th><th>Promoter</th><th>Status</th><th>Reviews</th><th>Action</th></tr></thead><tbody><?php foreach($opportunities as $op):?><tr><td><strong><?= e($op['title']) ?></strong><small><?= e($op['creator_name']) ?></small></td><td><?= e($op['organization_name']) ?></td><td><span class="admin-badge <?= strtolower($op['status']) ?>"><?= e(str_replace('_',' ',$op['status'])) ?></span></td><td><?= (int)$op['approved_reviews'] ?>/<?= count(INVESTMENT_REVIEW_AREAS) ?></td><td><a class="admin-button" href="admin-investment-review?id=<?= e($op['id']) ?>">Review</a></td></tr><?php endforeach;?></tbody></table></div></section>
